class Solution {
public:
    int maximumDifference(vector<int>& nums) {
        int min_val = nums[0];
        int max_diff = -1;
        for (size_t i = 1; i < nums.size(); ++i) {
            if (nums[i] > min_val) {
                max_diff = max(max_diff, nums[i] - min_val);
            } else {
                min_val = nums[i];
            }
        }
        return max_diff;
    }
};

class Solution {
    public int maximumDifference(int[] nums) {
        int minVal = nums[0];
        int maxDiff = -1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > minVal) {
                maxDiff = Math.max(maxDiff, nums[i] - minVal);
            } else {
                minVal = nums[i];
            }
        }
        return maxDiff;
    }
}

var maximumDifference = function(nums) {
  let minVal = nums[0];
  let maxDiff = -1;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > minVal) {
      maxDiff = Math.max(maxDiff, nums[i] - minVal);
    } else {
      minVal = nums[i];
    }
  }
  return maxDiff;
};
